import React, { useState } from 'react';
import { Link2, Copy, X, Users, Share } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import toast from 'react-hot-toast';
import api from '../utils/api';
import '../styles/invite-modal.css';

export default function InviteModal({ groupId, onClose }) {
  const [inviteData, setInviteData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);

  const generateInviteCode = async () => {
    setGenerating(true);
    try {
      const response = await api.post(`/groups/${groupId}/invite`);
      setInviteData(response.data);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to generate invite code');
    } finally {
      setGenerating(false);
    }
  };

  const copyToClipboard = (text, type) => {
    navigator.clipboard.writeText(text);
    toast.success(`${type} copied to clipboard!`);
  };

  const shareInvite = async () => {
    if (navigator.share && inviteData) {
      try {
        await navigator.share({
          title: 'Join my group',
          text: `Join my group "${inviteData.groupName || 'Expense Group'}" using this invite link: ${inviteData.inviteLink}`,
          url: inviteData.inviteLink
        });
      } catch (error) {
        // Fallback to copying if share fails
        copyToClipboard(inviteData.inviteLink, 'Invite link');
      }
    } else {
      // Fallback for browsers that don't support Web Share API
      copyToClipboard(inviteData.inviteLink, 'Invite link');
    }
  };

  const modalVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1 }
  };

  const contentVariants = {
    hidden: { y: 50, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  return (
    <AnimatePresence>
      <motion.div
        className="modal-overlay"
        variants={modalVariants}
        initial="hidden"
        animate="visible"
        exit="hidden"
      >
        <motion.div
          className="modal-content invite-modal"
          variants={contentVariants}
          initial="hidden"
          animate="visible"
          exit="hidden"
        >
          <div className="modal-header">
            <div className="header-title">
              <Users size={24} />
              <h2>Invite Members</h2>
            </div>
            <button className="close-btn" onClick={onClose}>
              <X size={24} />
            </button>
          </div>

          <div className="modal-body">
            {!inviteData ? (
              <div className="generate-invite">
                <div className="invite-icon">
                  <Link2 size={48} />
                </div>
                <h3>Generate Invite Code</h3>
                <p>
                  Create a unique invite code that members can use to join this group.
                  Only admins can generate invite codes.
                </p>
                <button
                  className="generate-btn"
                  onClick={generateInviteCode}
                  disabled={generating}
                >
                  {generating ? (
                    <>
                      <div className="btn-spinner"></div>
                      Generating...
                    </>
                  ) : (
                    <>
                      <Link2 size={20} />
                      Generate Invite Code
                    </>
                  )}
                </button>
              </div>
            ) : (
              <div className="invite-details">
                <div className="success-message">
                  <div className="success-icon">?</div>
                  <h3>Invite Code Generated!</h3>
                  <p>Share this with people you want to invite to the group.</p>
                </div>

                <div className="invite-sections">
                  <div className="invite-section">
                    <label>Invite Code</label>
                    <div className="code-box">
                      <span className="code-text">{inviteData.inviteCode}</span>
                      <button
                        className="copy-btn"
                        onClick={() => copyToClipboard(inviteData.inviteCode, 'Invite code')}
                      >
                        <Copy size={16} />
                      </button>
                    </div>
                  </div>

                  <div className="invite-section">
                    <label>Invite Link</label>
                    <div className="link-box">
                      <span className="link-text">{inviteData.inviteLink}</span>
                      <button
                        className="copy-btn"
                        onClick={() => copyToClipboard(inviteData.inviteLink, 'Invite link')}
                      >
                        <Copy size={16} />
                      </button>
                    </div>
                  </div>
                </div>

                <div className="invite-actions">
                  <button className="share-btn" onClick={shareInvite}>
                    <Share size={20} />
                    Share Invite
                  </button>
                  <button
                    className="regenerate-btn"
                    onClick={generateInviteCode}
                    disabled={generating}
                  >
                    {generating ? (
                      <>
                        <div className="btn-spinner"></div>
                        Regenerating...
                      </>
                    ) : (
                      'Generate New Code'
                    )}
                  </button>
                </div>

                <div className="invite-note">
                  <p>
                    <strong>Note:</strong> Anyone with this invite code can join the group. 
                    Share it only with people you trust.
                  </p>
                </div>
              </div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
